namespace Tailor360.Modules.Media.Domain.Media;

/// <summary>
/// A thumbnail or preview variant of a <see cref="MediaObject"/>, generated by issue #593's worker.
/// </summary>
/// <remarks>
/// The table this maps to is created by issue #592, per <c>module-ownership.md</c> §3's "first issue"
/// convention — but nothing in #592 constructs a row, so this type carries no public factory yet.
/// Adding one belongs to #593, which is what generates derivatives.
/// </remarks>
public sealed class MediaDerivative
{
    private MediaDerivative()
    {
        // The persistence layer materialises instances through this constructor. Populated by #593.
    }

    /// <summary>Identity of the derivative.</summary>
    public Guid Id { get; private set; }

    /// <summary>The object this is a derivative of.</summary>
    public Guid MediaObjectId { get; private set; }

    /// <summary>Which variant this is.</summary>
    public MediaDerivativeVariant Variant { get; private set; }

    /// <summary>The object-storage key this variant lives under. Its own random key, never derived from the original's.</summary>
    public string ObjectKey { get; private set; } = string.Empty;

    /// <summary>The variant's content type.</summary>
    public string ContentType { get; private set; } = string.Empty;

    /// <summary>The size of the variant's bytes.</summary>
    public long SizeBytes { get; private set; }

    /// <summary>The variant's pixel width.</summary>
    public int WidthPx { get; private set; }

    /// <summary>The variant's pixel height.</summary>
    public int HeightPx { get; private set; }

    /// <summary>When the variant was generated.</summary>
    public DateTimeOffset CreatedAt { get; private set; }
}

/// <summary>Which derivative of the original a <see cref="MediaDerivative"/> is.</summary>
public enum MediaDerivativeVariant
{
    /// <summary>A small preview for a grid or list.</summary>
    Thumbnail = 0,

    /// <summary>A larger preview for the full-screen zoom view.</summary>
    Preview = 1,
}
